  const members=rowMembers(a),key=input.dataset.inline,row=state.inline.get(a.id)||{registerId:a.registerId,assessmentId:a.id,revision:a.revision,groupRevisions:members.length>1?members.map(m=>({id:m.id,revision:m.revision})):undefined,paperReview:{fileId:a.paperFileId,sha256:a.paperSHA256||null},changes:{}};
