 function showAnswerDialog(){const a=state.detail.assessment,dialog=document.createElement('dialog');dialog.id='as-submit-dialog';dialog.className='as-workspace as-paper-dialog';dialog.setAttribute('aria-labelledby','as-answer-title');dialog.innerHTML='<div class="as-toolbar"><h3 id="as-answer-title">Submit answer</h3>'+button('Close','close-answer','',true)+'</div><p data-paper-message role="status" aria-live="polite"></p>'+button('Retry last action','retry','hidden',true)+answerUploadHTML(a,state.detail.learners[0]);dialog.addEventListener('cancel',event=>{event.preventDefault();void closeAnswerDialog();});state.host.appendChild(dialog);dialog.showModal();}
 async function closeAnswerDialog(){if(!canLeave())return;const id=state.detail?.assessment.id;state.answerOnly=false;state.detail=null;state.dirty=false;state.pending=null;document.getElementById('as-submit-dialog')?.close();await render();[...state.host.querySelectorAll('[data-as=submit-answer]')].find(b=>b.dataset.id===id)?.focus();}
 async function download(fileId,save=true,assessmentId=state.detail?.assessment.id){const blob=await api('download',{fileId,...(assessmentId?{assessmentId}:{}),operationId:crypto.randomUUID()},true);if(save){if(blob.type.split(';')[0]==='application/pdf')showPdf(blob);else{const url=URL.createObjectURL(blob);state.urls.push(url);const link=document.createElement('a');link.href=url;link.download='academy-assessment.'+(blob.type==='image/png'?'png':'jpg');link.click();}}return blob;}
 function showPdf(blob){
  document.getElementById('as-pdf-dialog')?.close();
  const url=URL.createObjectURL(blob);state.urls.push(url);
  const dialog=document.createElement('dialog');dialog.id='as-pdf-dialog';dialog.className='as-answer-dialog';dialog.setAttribute('aria-label','Assessment PDF');
  dialog.innerHTML=`<div class="as-toolbar"><h3>Assessment PDF</h3><button type="button" class="as-button as-secondary" data-pdf-close>Close</button></div><iframe src="/pdf-viewer/web/viewer.html?academy=1&amp;assessment=1&amp;file=${encodeURIComponent(url)}" title="Assessment PDF"></iframe><div class="as-actions"><button type="button" class="as-button as-secondary" data-pdf-print>Print</button><a class="as-button as-secondary" href="${esc(url)}" download="academy-assessment.pdf">Download PDF</a></div>`;
  dialog.addEventListener('close',()=>{URL.revokeObjectURL(url);state.urls=state.urls.filter(value=>value!==url);dialog.remove();});
  dialog.querySelector('[data-pdf-close]').onclick=()=>dialog.close();dialog.querySelector('[data-pdf-print]').onclick=()=>{const print=dialog.querySelector('iframe').contentWindow.M4L_ASSESSMENT_PRINT;if(print)print();};document.body.appendChild(dialog);dialog.showModal();
 }
