  if(action==='open-submission'){const data=state.progress.get(b.dataset.parent),c=data?.classes.find(c=>c.assessmentId===b.dataset.id),student=c?.students.find(r=>r.accountId===b.dataset.account);if(!student)return;await run(async()=>{await download(student.fileId,true,c.assessmentId);student.viewed=true;},render,{progressMessage:'Opening submission…',successMessage:'Check the complete PDF for the correct work and legibility before confirming receipt.'});return;}
  if(action==='confirm-receipt'){if(state.inline.size||state.scheduleDrafts.length){message('Save all table changes before confirming receipt.',true);return;}const data=state.progress.get(b.dataset.parent),c=data?.classes.find(c=>c.assessmentId===b.dataset.id),student=c?.students.find(r=>r.accountId===b.dataset.account);if(!student?.viewed||!window.confirm('Confirm receipt of '+student.name+'’s submission?\n\nI checked that this is the correct submission and that all pages are legible.'))return;const body={operationId:crypto.randomUUID(),assessmentId:c.assessmentId,revision:c.revision,recipientRevision:student.revision,accountId:student.accountId,submissionId:student.submissionId};await run(()=>api('confirm-submission',body),async()=>{state.progress.set(b.dataset.parent,await api('progress-list',{assessmentId:b.dataset.parent}));await refresh();},{progressMessage:'Confirming receipt…',successMessage:'Receipt confirmed.'});return;}

  if(action==='preview-answer'){const file=state.host.querySelector('[name=answer]')?.files?.[0];if(!file||file.type!=='application/pdf'&&!/\.pdf$/i.test(file.name)){message('Choose an answer PDF to preview.',true);return;}state.answerPreviewed=true;showPdf(file);return;}
  if(action==='close-marks'){await closeMarksDialog();return;}
