   const assessment=draft?{...original,...draft,id:original?.id||draft.clientId,subject:state.list.catalogue?.find(c=>c.key===draft.catalogueKey)?.label||draft.subject,canAdmin:true,draftOnly:!original}:original;
   state.detail={assessment,group:members.length?{canManage:true,members}:null,learners:[],draftClientId:draft?.clientId};state.paperOnly='schedule';state.dirty=false;await render();return;
