  if(action==='open-assessment-pdf'){if(!canLeave(true))return;await run(async()=>{const detail=await api('get',{assessmentId:b.dataset.id});if((!detail.assessment.canTeach&&!detail.assessment.paperAvailable)||!detail.assessment.paperFileId)throw new Error('This assessment paper is not available yet.');await download(detail.assessment.paperFileId,true,detail.assessment.id);},async()=>{},{progressMessage:'Opening assessment…',successMessage:'Assessment opened in PDF.js.'});return;}
