  if(action==='paper-moderation'||action==='review-paper-row'){if(!canLeave())return;await run(async()=>{const detail=await api('get',{assessmentId:b.dataset.id});if(!detail.assessment.canAdmin)throw new Error('Paper moderation requires current Admin access.');state.detail=detail;state.paperOnly='moderation';},render);return;}
