    await run(async()=>{state.registerValidation={id:b.dataset.id,signature,result:await api('register-validate',body)};},async()=>{state.host.querySelector('[data-register-validation="'+b.dataset.id+'"]').innerHTML=window.M4L_ASSESSMENT_REGISTER.validationHTML(state.registerValidation.result);},{preserveDirty:true,successMessage:'Validation completed.'});return;
